using System.Net;
using System.Text.Json;
using Htt.Host.Api.MasterData;
using Htt.Host.Api.Purchasing;
using Htt.Host.Api.Sales;
using Htt.Host.Api.Accounting;
using Htt.Infrastructure;
using Npgsql;
using Xunit;
using static Htt.IntegrationTests.SalesFlowSupport;
namespace Htt.IntegrationTests;
public sealed class FullBasTests:IAsyncLifetime
{
 private readonly DatabaseFixture db=new();public Task InitializeAsync()=>db.InitializeAsync();public Task DisposeAsync()=>db.DisposeAsync();
 private Task<object?> S(string sql,params(string,object)[]args)=>db.OwnerScalarAsync(sql,args);
 private async Task<DateOnly> Today()=>DateOnly.Parse((string)(await S("SELECT to_char((now() AT TIME ZONE timezone)::date,'YYYY-MM-DD') FROM core.companies WHERE id=@company",("company",db.Company)))!);
 private static Guid Id(JsonElement e)=>e.GetProperty("id").GetGuid();
 private static decimal T(JsonElement e,string key)=>D(e.GetProperty("financial").GetProperty(key));
 private async Task<JsonElement> Report(HttpClient c,DateOnly? from=null,DateOnly? to=null,string suffix="",string method="ACCOUNTS")=>await Get(c,$"/accounting/reports/gst-bas?reportingMethod=FULL&calculationMethod={method}&from={from??await Today():yyyy-MM-dd}&to={to??(await Today()).AddDays(1):yyyy-MM-dd}{suffix}");
 private async Task<BasPeriodInput> Input()=>new(Code(),await Today(),(await Today()).AddDays(1),"CUSTOM","NON_CASH","FULL",true);
 private async Task<JsonElement> CreatePeriod(HttpClient c,BasPeriodInput? input=null)=>await Expect(await Send(c,HttpMethod.Post,"/accounting/bas-periods",input??await Input()),HttpStatusCode.Created);
 private static Task<HttpResponseMessage> Action(HttpClient c,Guid id,string action="finalize",long? version=1,string? key=null,DateOnly? lodged=null)=>Send(c,HttpMethod.Post,$"/accounting/bas-periods/{id}/{action}",new BasActionInput("ref-"+(key??Code()),"Finance review",lodged),version,key);
 private async Task<(SalesData Data,Guid Invoice,Guid Line,Guid OrderLine)> Invoice(HttpClient c,string basis="NON_CASH")
 {
  await CompanyTaxSettings.ConfigureAsync(db.Owner,db.Company,true,basis,DatabaseFixture.Issuer,db.Subject);var d=await Setup(db,c,0);var p=await Get(c,$"/products/{d.Product}");await Expect(await Send(c,HttpMethod.Put,$"/products/{d.Product}",new ProductMaintenance(p.GetProperty("sku").GetString()!,"Report service",p.GetProperty("taxCodeId").GetGuid(),ItemType:"SERVICE",WholePacks:false),1),HttpStatusCode.OK);
  var q=await Submitted(c,d.Draft(1)with{Lines=[new(d.BoxUnit,Quantity:1,UnitPrice:100)]});var o=(await Expect(await Approve(c,q.Id,q.Version),HttpStatusCode.Created)).GetProperty("orderId").GetGuid();var ol=(await Get(c,$"/sales-orders/{o}")).GetProperty("lines")[0].GetProperty("id").GetGuid();var v=(await Get(c,$"/sales-orders/{o}/invoiceable")).GetProperty("version").GetInt64();var i=await Expect(await Send(c,HttpMethod.Post,$"/sales-orders/{o}/invoices",new InvoiceInput([new(ol,1)],"Service completed"),v),HttpStatusCode.Created);return(d,i.GetProperty("id").GetGuid(),i.GetProperty("lines")[0].GetProperty("id").GetGuid(),ol);
 }
 private async Task<(Guid Supplier,Guid Bill,Guid Line,Guid Expense)> Bill(HttpClient c,DateOnly? date=null,DateOnly? due=null,string basis="NON_CASH",DateOnly? held=null,DateOnly? posting=null,bool recoverable=true,decimal net=100,decimal taxAmount=10)
 {
  await CompanyTaxSettings.ConfigureAsync(db.Owner,db.Company,true,basis,DatabaseFixture.Issuer,db.Subject);var supplier=await Create(c,"/suppliers",new SupplierMaintenance(Code(),"Report supplier",null));var account=(Guid)(await S("INSERT INTO accounting.accounts(company_id,code,name,kind) VALUES(@company,@code,'Report expense','EXPENSE') RETURNING id",("company",db.Company),("code",Code())))!;var tax=(Guid)(await S("SELECT id FROM accounting.tax_codes WHERE company_id=@company AND code=CASE WHEN @free THEN 'FRE' ELSE 'GST' END",("company",db.Company),("free",taxAmount==0)))!;var dt=date??await Today();var b=await Expect(await Send(c,HttpMethod.Post,"/supplier-expense-bills",new ExpenseBillInput(supplier,Code(),dt,due??dt.AddDays(30),posting??dt,[new(account,"Expense",net,taxAmount,tax,recoverable)],Code(),held??dt)),HttpStatusCode.Created);return(supplier,b.GetProperty("bill").GetProperty("id").GetGuid(),b.GetProperty("lines")[0].GetProperty("id").GetGuid(),account);
 }

 private static decimal F(JsonElement e,string key)=>D(e.GetProperty("financial").GetProperty("full").GetProperty(key));
 private static decimal W(JsonElement e,string key)=>D(e.GetProperty("worksheet").GetProperty(key));
 private static Task<HttpResponseMessage> Classify(HttpClient c,string kind,Guid id,string purchase="NON_CAPITAL",string sales="AUTO",decimal? percent=null,long version=0,string? key=null)=>Send(c,HttpMethod.Put,$"/accounting/bas-classifications/{kind}/{id}",new BasClassificationInput(sales,purchase,percent,"Finance classification"),version,key);
 private static async Task SetClass(HttpClient c,Guid line,string purchase="NON_CAPITAL",decimal? percent=null)=>await Expect(await Classify(c,"BILL_LINE",line,purchase,percent:percent),HttpStatusCode.OK);
    private async Task<(SalesData Data,Guid Order,Guid Line)> Order(HttpClient c,string basis="CASH",decimal price=22,decimal quantity=2,string? taxCode=null)
    {
        // Fixture companies host independent test customers with both tax bases; owner setup changes the test-only default.
        await S("UPDATE core.companies SET gst_registered=true,gst_basis=@basis WHERE id=@company",("company",db.Company),("basis",basis));
        var d=await Setup(db,c,0);var p=await Get(c,$"/products/{d.Product}");var tax=p.GetProperty("taxCodeId").GetGuid();
        if(taxCode is not null)tax=(await Get(c,"/foundation")).GetProperty("taxCodes").EnumerateArray().Single(t=>t.GetProperty("code").GetString()==taxCode).GetProperty("id").GetGuid();
        await Expect(await Send(c,HttpMethod.Put,$"/products/{d.Product}",new ProductMaintenance(p.GetProperty("sku").GetString()!,"Installation",tax,ItemType:"SERVICE",WholePacks:false),1),HttpStatusCode.OK);
        var q=await Submitted(c,d.Draft(quantity) with{Lines=[new(d.BoxUnit,Quantity:quantity,UnitPrice:price)]});var o=(await Expect(await Approve(c,q.Id,q.Version),HttpStatusCode.Created)).GetProperty("orderId").GetGuid();
        return(d,o,(await Get(c,$"/sales-orders/{o}")).GetProperty("lines")[0].GetProperty("id").GetGuid());
    }
    private static async Task<JsonElement> InvoiceOrder(HttpClient c,Guid order,Guid line,decimal quantity=2)
    {
        var v=(await Get(c,$"/sales-orders/{order}/invoiceable")).GetProperty("version").GetInt64();
        return await Expect(await Send(c,HttpMethod.Post,$"/sales-orders/{order}/invoices",new InvoiceInput([new(line,quantity)],"Work completed"),v),HttpStatusCode.Created);
    }
    private static Guid InvoiceLine(JsonElement invoice)=>invoice.GetProperty("lines")[0].GetProperty("id").GetGuid();
    private static Task<HttpResponseMessage> Receipt(HttpClient c,Guid customer,decimal amount,Guid? invoice=null,Guid? orderLine=null,string? key=null,string? reference=null,DateOnly? date=null)=>
        Send(c,HttpMethod.Post,$"/customers/{customer}/receipts",new CustomerReceiptInput(amount,"BANK_TRANSFER",reference??Code(),invoice is {} i?[new(i,amount)]:[],orderLine is {} l?[new(l,amount)]:[],date),key:key);
    private static Task<HttpResponseMessage> Apply(HttpClient c,Guid advance,Guid invoiceLine,decimal amount,string? key=null,string? reference=null)=>
        Send(c,HttpMethod.Post,$"/customer-advances/{advance}/apply",new AdvanceApplicationInput(reference??Code(),[new(invoiceLine,amount)]),key:key);
    private static Guid Advance(JsonElement receipt)=>receipt.GetProperty("advances")[0].GetProperty("id").GetGuid();


 [Theory][InlineData("ACCOUNTS")][InlineData("WORKSHEET")]
 public async Task Empty_Full_BAS_has_all_labels_exact_zero_and_legacy_read_is_unchanged(string method)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Report(c,method:method);Assert.Equal("READY",x.GetProperty("status").GetString());for(var n=1;n<=20;n++)Assert.Equal(0,W(x,"G"+n));foreach(var k in new[]{"G1","G2","G3","G10","G11","1A","1B","netGst"})Assert.Equal(0,F(x,k));var legacy=await Get(c,$"/accounting/reports/gst-bas?from={await Today():yyyy-MM-dd}&to={(await Today()).AddDays(1):yyyy-MM-dd}");Assert.False(legacy.GetProperty("financial").TryGetProperty("full",out _));}
 [Theory][InlineData("CASH","ACCOUNTS")][InlineData("NON_CASH","ACCOUNTS")][InlineData("CASH","WORKSHEET")][InlineData("NON_CASH","WORKSHEET")]
 public async Task Classified_sales_and_purchases_reconcile_all_worksheet_equations(string basis,string method)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var i=await Invoice(c,basis);var b=await Bill(c,basis:basis);await SetClass(c,b.Line);if(basis=="CASH"){await Expect(await Send(c,HttpMethod.Post,$"/customers/{i.Data.Customer}/receipts",new CustomerReceiptInput(55,"BANK_TRANSFER",Code(),[new(i.Line,55)])),HttpStatusCode.Created);await Expect(await Send(c,HttpMethod.Post,$"/suppliers/{b.Supplier}/payments",new SupplierPaymentInput(55,"BANK_TRANSFER",Code(),Allocations:[new(b.Line,55)])),HttpStatusCode.Created);}var x=await Report(c,method:method);var gross=basis=="CASH"?55:110;Assert.Equal(gross,F(x,"G1"));Assert.Equal(gross,F(x,"G11"));Assert.Equal(gross/11,F(x,"1A"));Assert.Equal(gross/11,F(x,"1B"));Assert.Equal("READY",x.GetProperty("status").GetString());Assert.Equal("RECONCILED",x.GetProperty("ledgerStatus").GetString());Assert.Equal(W(x,"G2")+W(x,"G3")+W(x,"G4"),W(x,"G5"));Assert.Equal(W(x,"G1")-W(x,"G5"),W(x,"G6"));Assert.Equal(W(x,"G6")+W(x,"G7"),W(x,"G8"));Assert.Equal(W(x,"G10")+W(x,"G11"),W(x,"G12"));Assert.Equal(W(x,"G13")+W(x,"G14")+W(x,"G15"),W(x,"G16"));Assert.Equal(W(x,"G12")-W(x,"G16"),W(x,"G17"));Assert.Equal(W(x,"G17")+W(x,"G18"),W(x,"G19"));Assert.Equal(0,W(x,"salesCalculationDifference"));Assert.Equal(0,W(x,"purchaseCalculationDifference"));}
 [Theory][InlineData("CAPITAL",110,0)][InlineData("NON_CAPITAL",0,110)]
 public async Task Purchase_class_splits_capital_from_noncapital_without_reposting_GL(string category,decimal capital,decimal noncapital)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Bill(c);Assert.Equal("INCOMPLETE",(await Report(c)).GetProperty("status").GetString());var before=await S("SELECT count(*) FROM accounting.journal_entries WHERE company_id=@company",("company",db.Company));await SetClass(c,b.Line,category);var x=await Report(c);Assert.Equal(capital,F(x,"G10"));Assert.Equal(noncapital,F(x,"G11"));Assert.Equal(10,F(x,"1B"));Assert.Equal(before,await S("SELECT count(*) FROM accounting.journal_entries WHERE company_id=@company",("company",db.Company)));}
 [Theory][InlineData(0,0,110)][InlineData(100,110,0)][InlineData(25,27.5,82.5)]
 public async Task Non_creditable_purpose_split_is_explicit_and_does_not_create_a_GST_claim(decimal percent,decimal inputTaxed,decimal privatePart)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Bill(c,recoverable:false);await SetClass(c,b.Line);Assert.Equal("INCOMPLETE",(await Report(c)).GetProperty("status").GetString());await Expect(await Classify(c,"BILL_LINE",b.Line,percent:percent,version:1),HttpStatusCode.OK);var x=await Report(c,method:"WORKSHEET");Assert.Equal(inputTaxed,W(x,"G13"));Assert.Equal(privatePart,W(x,"G15"));Assert.Equal(0,W(x,"G17"));Assert.Equal(0,F(x,"1B"));Assert.Equal("READY",x.GetProperty("status").GetString());}
 [Fact] public async Task Purchases_without_GST_use_G14_once_and_excluded_outgoings_do_not_inflate_G11()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Bill(c,recoverable:false,taxAmount:0);await SetClass(c,b.Line,percent:100);var x=await Report(c);Assert.Equal(100,W(x,"G14"));Assert.Equal(0,W(x,"G13"));Assert.Equal(0,W(x,"G15"));await Expect(await Classify(c,"BILL_LINE",b.Line,"EXCLUDED",version:1),HttpStatusCode.OK);Assert.Equal(0,F(await Report(c),"G11"));}
 [Theory][InlineData("EXPORT","G2")][InlineData("OTHER_GST_FREE","G3")]
 public async Task GST_free_sales_require_export_or_domestic_classification(string classification,string label)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var(d,o,l)=await Order(c,"NON_CASH",100,1,"FRE");await InvoiceOrder(c,o,l,1);Assert.Equal("INCOMPLETE",(await Report(c)).GetProperty("status").GetString());var tax=(await Get(c,$"/products/{d.Product}")).GetProperty("taxCodeId").GetGuid();await Expect(await Classify(c,"TAX_CODE",tax,purchase:"AUTO",sales:classification),HttpStatusCode.OK);var x=await Report(c);Assert.Equal(100,F(x,label));Assert.Equal(100,F(x,"G1"));Assert.Equal(0,W(x,"G6"));Assert.Equal("READY",x.GetProperty("status").GetString());}
