 [Theory][InlineData("ACCOUNTS")][InlineData("WORKSHEET")]
 public async Task Full_snapshot_reopen_and_lodgement_preserve_original_classifications(string method)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Bill(c);await SetClass(c,b.Line,"CAPITAL");var p=await CreatePeriod(c,(await Input())with{CalculationMethod=method});var f=await Expect(await Action(c,Id(p)),HttpStatusCode.OK);var sid=f.GetProperty("snapshotId").GetGuid();var first=await Get(c,$"/accounting/bas-snapshots/{sid}");Assert.Equal(110,F(first.GetProperty("report"),"G10"));await Expect(await Classify(c,"BILL_LINE",b.Line,version:1),HttpStatusCode.Conflict);await Expect(await Action(c,Id(p),"record-lodgement",2,lodged:await Today()),HttpStatusCode.OK);await Expect(await Action(c,Id(p),"reopen",3),HttpStatusCode.OK);await Expect(await Classify(c,"BILL_LINE",b.Line,version:1),HttpStatusCode.OK);await Expect(await Action(c,Id(p),version:4),HttpStatusCode.OK);Assert.Equal(first.GetRawText(),(await Get(c,$"/accounting/bas-snapshots/{sid}")).GetRawText());Assert.Equal(110,F(await Report(c),"G11"));}
 [Fact] public async Task Historical_Simpler_snapshot_is_not_reinterpreted_by_Full_classification()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Bill(c);var p=await CreatePeriod(c,(await Input())with{ReportingMethod="SIMPLER"});var f=await Expect(await Action(c,Id(p)),HttpStatusCode.OK);var id=f.GetProperty("snapshotId").GetGuid();var before=await Get(c,$"/accounting/bas-snapshots/{id}");await SetClass(c,b.Line,"CAPITAL");Assert.Equal(before.GetRawText(),(await Get(c,$"/accounting/bas-snapshots/{id}")).GetRawText());}
 [Fact] public async Task Legal_adjustments_are_netted_once_at_G7_or_G18_not_a_balancing_plug()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var i=await Invoice(c);var b=await Bill(c);await SetClass(c,b.Line);await Expect(await Send(c,HttpMethod.Post,$"/sales-invoices/{i.Invoice}/amount-credit-notes",new AmountCreditInput("Credit",[new(i.Line,20,2,"Reduction")])),HttpStatusCode.Created);await Expect(await Send(c,HttpMethod.Post,$"/supplier-bills/{b.Bill}/amount-credits",new SupplierAmountCreditInput(Code(),"Credit",[new(b.Line,10,1,"Reduction")])),HttpStatusCode.Created);var x=await Report(c,method:"WORKSHEET");Assert.Equal(110,W(x,"G1"));Assert.Equal(110,W(x,"G11"));Assert.Equal(0,W(x,"G7"));Assert.Equal(11,W(x,"G18"));Assert.Equal(10,F(x,"1A"));Assert.Equal(11,F(x,"1B"));Assert.Equal(-1,F(x,"netGst"));var accounts=await Report(c);Assert.Equal(88,F(accounts,"G1"));Assert.Equal(99,F(accounts,"G11"));Assert.Equal(F(accounts,"netGst"),F(x,"netGst"));}
 [Theory][InlineData(0,2)][InlineData(20,0)]
 public async Task Tax_only_and_net_only_credits_use_actual_adjustment_tax(decimal net,decimal tax)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var i=await Invoice(c);await Expect(await Send(c,HttpMethod.Post,$"/sales-invoices/{i.Invoice}/amount-credit-notes",new AmountCreditInput("Credit",[new(i.Line,net,tax,"Correction")])),HttpStatusCode.Created);var x=await Report(c,method:"WORKSHEET");Assert.Equal(110,W(x,"G1"));Assert.Equal(tax*11,W(x,"G18"));Assert.Equal(10-tax,F(x,"netGst"));Assert.Equal("READY",x.GetProperty("status").GetString());}
