 [Fact] public async Task Classification_concurrency_is_idempotent_and_revision_protected()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Bill(c);var key=Code();var all=await Task.WhenAll(Enumerable.Range(0,4).Select(_=>Classify(c,"BILL_LINE",b.Line,key:key)));foreach(var x in all)await Expect(x,HttpStatusCode.OK);var race=await Task.WhenAll(Classify(c,"BILL_LINE",b.Line,"CAPITAL",version:1),Classify(c,"BILL_LINE",b.Line,"EXCLUDED",version:1));Assert.Single(race,x=>x.StatusCode==HttpStatusCode.OK);Assert.Single(race,x=>x.StatusCode==HttpStatusCode.Conflict);var h=await Get(c,$"/accounting/bas-classifications/BILL_LINE/{b.Line}");Assert.Equal(2,h.GetProperty("history").GetArrayLength());}
