 [Theory][InlineData(true)][InlineData(false)]
 public async Task Full_finalization_and_classification_serialize_in_both_orders(bool finalFirst)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Bill(c);await SetClass(c,b.Line);var p=await CreatePeriod(c);await using var s=await db.SessionAsync();if(finalFirst){await Sql.RowsAsync(s,"SELECT accounting.bas_transition(@id,1,'FINALIZED',@ref,'Reviewed',NULL)",default,("id",Id(p)),("ref",Code()));var change=Classify(c,"BILL_LINE",b.Line,"CAPITAL",version:1);await Task.Delay(100);Assert.False(change.IsCompleted);await s.Transaction.CommitAsync();await Expect(await change,HttpStatusCode.Conflict);}else{await Sql.RowsAsync(s,"SELECT accounting.bas_classify('BILL_LINE',@line,1,'AUTO','CAPITAL',NULL,'Reviewed')",default,("line",b.Line));var finishing=Action(c,Id(p));await Task.Delay(100);Assert.False(finishing.IsCompleted);await s.Transaction.CommitAsync();var f=await Expect(await finishing,HttpStatusCode.OK);var frozen=await Get(c,$"/accounting/bas-snapshots/{f.GetProperty("snapshotId").GetGuid()}");Assert.Equal(110,F(frozen.GetProperty("report"),"G10"));}}
 [Fact] public async Task Readers_during_uncommitted_reclassification_see_one_complete_version()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Bill(c);await SetClass(c,b.Line);await using var s=await db.SessionAsync();await Sql.RowsAsync(s,"SELECT accounting.bas_classify('BILL_LINE',@line,1,'AUTO','CAPITAL',NULL,'Reviewed')",default,("line",b.Line));var reads=await Task.WhenAll(Enumerable.Range(0,4).Select(_=>Report(c)));Assert.All(reads,x=>{Assert.Equal(110,F(x,"G11"));Assert.Equal(0,F(x,"G10"));});await s.Transaction.CommitAsync();Assert.Equal(110,F(await Report(c),"G10"));}
 [Fact] public async Task Audit_failure_rolls_back_classification_and_idempotency_then_same_key_retries()
