 {await using var api=new TestApi(db);using var c=api.Authenticated();var(d,o,l)=await Order(c,basis);var r=await Expect(await Receipt(c,d.Customer,1,orderLine:l),HttpStatusCode.Created);var first=await Report(c,method:"WORKSHEET");Assert.Equal(gross,F(first,"G1"));Assert.Equal(tax,F(first,"1A"));var i=await InvoiceOrder(c,o,l);await Expect(await Apply(c,Advance(r),InvoiceLine(i),1),HttpStatusCode.Created);var after=await Report(c,method:"WORKSHEET");Assert.Equal(gross,F(after,"G1"));Assert.Equal(tax,F(after,"1A"));Assert.Equal("RECONCILED",after.GetProperty("ledgerStatus").GetString());}
