Send(c,HttpMethod.Post,"/supplier-refunds",new SupplierRefundInput(22,Code(),"Refund",CreditLineId:cl)),HttpStatusCode.Created);Assert.Equal(88,F(await Report(c),"G10"));var refundId=refund.GetProperty("refund").GetProperty("id").GetGuid();await Expect(await Send(c,HttpMethod.Post,$"/supplier-refunds/{refundId}/reverse",new SupplierRefundReversalInput(Code(),"Correction")),HttpStatusCode.Created);x=await Report(c);Assert.Equal(110,F(x,"G10"));Assert.Equal(0,F(x,"purchaseGrossDifference"));}
 [Fact] public async Task Unmatched_GST_journal_never_becomes_a_fabricated_G7_or_G18_adjustment()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Bill(c);await SetClass(c,b.Line);var doc=(Guid)(await S("INSERT INTO platform.documents(company_id,document_type,business_date,created_by)VALUES(@company,'FULL_BAS_TEST',@date,@actor)RETURNING id",("company",db.Company),("date",await Today()),("actor",db.Actor)))!;await using(var session=await db.SessionAsync()){await Sql.RowsAsync(session,"SELECT accounting.post_journal(@doc,1,'FULL_BAS_TEST',@date,'Unmatched tax',jsonb_build_array(jsonb_build_object('accountId',(SELECT input_account_id FROM accounting.purchase_gst_entries WHERE company_id=core.current_company() LIMIT 1),'debit',1),jsonb_build_object('accountId',@expense,'credit',1)))",default,("doc",doc),("date",await Today()),("expense",b.Expense));await session.Transaction.CommitAsync();}var x=await Report(c,method:"WORKSHEET");Assert.Equal("UNRECONCILED",x.GetProperty("status").GetString());Assert.Equal(0,W(x,"G7"));Assert.Equal(0,W(x,"G18"));var p=await CreatePeriod(c);await Expect(await Action(c,Id(p)),HttpStatusCode.Conflict);}
