 private static Task<HttpResponseMessage> Method(HttpClient c,Guid id,string reporting="FULL",string calculation="WORKSHEET",long version=1,string? key=null)=>Send(c,HttpMethod.Put,$"/accounting/bas-periods/{id}/method",new BasMethodInput(reporting,calculation,"Finance method review"),version,key);
 [Fact] public async Task Open_Simpler_period_can_move_to_Full_without_rewriting_its_original_header()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Bill(c);await SetClass(c,b.Line,"CAPITAL");var p=await CreatePeriod(c,(await Input())with{ReportingMethod="SIMPLER"});var m=await Expect(await Method(c,Id(p)),HttpStatusCode.OK);Assert.Equal("FULL",m.GetProperty("reportingMethod").GetString());Assert.Equal("WORKSHEET",m.GetProperty("calculationMethod").GetString());Assert.Equal("SIMPLER",await S("SELECT reporting_method FROM accounting.bas_periods WHERE company_id=@company AND id=@id",("company",db.Company),("id",Id(p))));var f=await Expect(await Action(c,Id(p),version:2),HttpStatusCode.OK);var frozen=await Get(c,$"/accounting/bas-snapshots/{f.GetProperty("snapshotId").GetGuid()}");Assert.Equal("FULL_WORKSHEET",frozen.GetProperty("report").GetProperty("method").GetString());Assert.Equal(110,F(frozen.GetProperty("report"),"G10"));Assert.Single((await Get(c,$"/accounting/bas-periods/{Id(p)}/history")).GetProperty("methods").EnumerateArray());}
 [Fact] public async Task Frozen_method_changes_require_reopen_and_preserve_old_snapshot()
 {await using var api=new TestApi(db);using var c=api.Authenticated();await Invoice(c);var p=await CreatePeriod(c);var f=await Expect(await Action(c,Id(p)),HttpStatusCode.OK);var sid=f.GetProperty("snapshotId").GetGuid();var before=await Get(c,$"/accounting/bas-snapshots/{sid}");await Expect(await Method(c,Id(p),version:2),HttpStatusCode.Conflict);await Expect(await Action(c,Id(p),"reopen",2),HttpStatusCode.OK);await Expect(await Method(c,Id(p),version:3),HttpStatusCode.OK);await Expect(await Action(c,Id(p),version:4),HttpStatusCode.OK);Assert.True(JsonElement.DeepEquals(before,await Get(c,$"/accounting/bas-snapshots/{sid}")));}
 [Fact] public async Task Method_changes_are_idempotent_and_concurrent_versions_have_one_winner()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await CreatePeriod(c);var key=Code();var all=await Task.WhenAll(Enumerable.Range(0,4).Select(_=>Method(c,Id(p),key:key)));foreach(var r in all)await Expect(r,HttpStatusCode.OK);Assert.Single((await Get(c,$"/accounting/bas-periods/{Id(p)}/history")).GetProperty("methods").EnumerateArray());var race=await Task.WhenAll(Method(c,Id(p),calculation:"ACCOUNTS",version:2),Method(c,Id(p),reporting:"SIMPLER",calculation:"ACCOUNTS",version:2));Assert.Single(race,x=>x.StatusCode==HttpStatusCode.OK);Assert.Single(race,x=>x.StatusCode==HttpStatusCode.Conflict);await S("DELETE FROM identity.role_permissions WHERE company_id=@company AND permission_code='accounting.bas.manage'",("company",db.Company));await Expect(await Method(c,Id(p),key:key),HttpStatusCode.Forbidden);}
 [Fact] public async Task Failed_method_audit_rolls_back_history_and_control_for_same_key_retry()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await CreatePeriod(c);var key=Code();await S($"CREATE FUNCTION accounting.test_bas_method_failure()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.company_id='{db.Company}'::uuid AND NEW.action='accounting.bas_method_changed' THEN RAISE EXCEPTION 'Injected method audit' USING ERRCODE='HR422';END IF;RETURN NEW;END$$;CREATE TRIGGER test_bas_method_failure BEFORE INSERT ON platform.audit_events FOR EACH ROW EXECUTE FUNCTION accounting.test_bas_method_failure()");try{await Expect(await Method(c,Id(p),key:key),HttpStatusCode.UnprocessableEntity);Assert.Empty((await Get(c,$"/accounting/bas-periods/{Id(p)}/history")).GetProperty("methods").EnumerateArray());Assert.Equal(1,(await Get(c,$"/accounting/bas-periods/{Id(p)}")).GetProperty("version").GetInt64());}finally{await S("DROP TRIGGER test_bas_method_failure ON platform.audit_events;DROP FUNCTION accounting.test_bas_method_failure()");}await Expect(await Method(c,Id(p),key:key),HttpStatusCode.OK);}
